  user-select: none;
  white-space: nowrap;
}

.turnLabelFull,
.turnLabelCompact {
  grid-area: 1 / 1;
  max-width: 64px;
  overflow: hidden;
  opacity: 1;
  white-space: nowrap;
}

.turnLabelCompact {
  max-width: 0;
  opacity: 0;
}

.turnLabelActive {
  color: color-mix(
    in srgb,
    var(--dsw-static-blue-500) 55%,
    var(--dsw-alias-label-tertiary)
  );
  background: var(--trajectory-turn-accent);
}

.eventInner {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  min-width: 0;
  height: 100%;
}

.kindSlot {
  display: flex;
  flex: none;
  align-items: flex-end;
  justify-content: flex-end;
  width: 76px;
}

.kindSlot :global([role='tooltip']) {
  border: 1px solid var(--dsw-alias-border-l2);
  background: var(--dsw-alias-bg-layer-2);
  box-shadow: var(--dsw-shadow-lv2);
  color: var(--dsw-alias-label-primary);
}

.content {
  padding-left: 4px !important;
  color: var(--dsw-alias-label-primary);
}

.kindTag {
  display: inline-flex;
  flex: none;
  align-items: center;
  box-sizing: border-box;
  height: 19px;
  padding: 0 5px;
  border: 1px solid transparent;
  border-radius: 4px;
  font-size: 10px;
  line-height: 16px;
  font-weight: 650;
  letter-spacing: 0.035em;
  user-select: none;
}

.kindTagIcon {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: 0;
  height: 13px;
  overflow: hidden;
  opacity: 0;
  transform: scale(0.8);
}

.kindTagLabel {
  display: inline-block;
  max-width: 72px;
  overflow: hidden;
  opacity: 1;
  white-space: nowrap;
}

.table .kindSlot .message {
  justify-content: center;
  width: 100%;
}

@container trajectory-table (max-width: 620px) {
  .eventColumn {
    width: 50px;
  }

  .event {
    padding-right: 3px !important;
    padding-left: 28px !important;
  }

  .requestBoundaryControl {
    --request-boundary-base-left: 6px;
  }

  .kindSlot {
    width: 19px;
  }

  .kindTag,
  .table .kindSlot .message {
    justify-content: center;
    width: 19px;
    padding-right: 0;
    padding-left: 0;
  }

  .kindTagIcon {
    width: 13px;
    opacity: 1;
    transform: scale(1);
  }

  .kindTagLabel {
    max-width: 0;
    opacity: 0;
  }

  .turnLabelFull {
    max-width: 0;
    opacity: 0;
  }

  .turnLabelCompact {
    max-width: 64px;
    opacity: 1;
  }
}

@media (prefers-reduced-motion: no-preference) {
  .eventColumn,
  .event,
  .requestBoundaryControl,
  .kindSlot,
  .kindTag,
  .kindTagIcon,
  .kindTagLabel,
  .turnLabelFull,
  .turnLabelCompact {
    transition-duration: 180ms;
    transition-timing-function: var(--ds-ease-in-out);
  }

  .eventColumn,
  .kindSlot {
    transition-property: width;
  }

  .event {
    transition-property: padding-right, padding-left;
  }

  .requestBoundaryControl {
    transition-property: left;
  }

  .kindTag {
    transition-property: padding-right, padding-left;
  }

  .kindTagIcon {
    transition-property: width, opacity, transform;
  }

  .kindTagLabel,
  .turnLabelFull,
  .turnLabelCompact {
    transition-property: max-width, opacity;
  }
}

